var fp = PhaseManager.get_current_phase_instance()
for uid in GameState.state.units:
	if fp.sequencer_11e.eligible_to_fight(uid, GameState.state):
		fp.sequencer_11e.mark_fought(uid, GameState.state)
return fp.get_end_fight_status().step_over

var ph = PhaseManager.get_current_phase_instance()
if int(ph.consolidating_player_11e) == 2:
	tree.root.get_node("Main/HUD_Right/VBoxContainer/FightScrollContainer/FightPanel/ConsolidationStepPanel/EndConsolidationButton").pressed.emit()
return true

var ob = tree.root.get_node("ConsolidateDialog/Content/ModePicker/ModeOption")
var out = []
for i in range(ob.item_count):
	out.append(ob.get_item_text(i))
print("[cus11e unstoppable] modes: ", out)
return " | ".join(out)

var ob = tree.root.get_node("ConsolidateDialog/Content/ModePicker/ModeOption")
ob.select(2)
ob.item_selected.emit(2)
return ob.get_item_text(ob.selected)
